import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const out = path.join(__dirname, '..', 'src', 'main.jsx');

const jsx = "import React, { useEffect, useState, useCallback } from 'react';\nimport { createRoot } from 'react-dom/client';\nimport './styles.css';\n\n// ── Utilities ─────────────────────────────────────────────────────────────────\nasync function request(url, method = 'GET', body) {\n  const res = await fetch(url, {\n    method,\n    credentials: 'include',\n    headers: body ? { 'Content-Type': 'application/json' } : undefined,\n    body: body ? JSON.stringify(body) : undefined\n  });\n  let data;\n  try {\n    data = await res.json();\n  } catch {\n    throw new Error('Service unavailable. Please refresh in a moment.');\n  }\n  if (!res.ok) {\n    const e = new Error(data.error || data.message || 'Request failed.');\n    e.status = res.status;\n    e.data = data;\n    throw e;\n  }\n  return data;\n}\nfunction fields(f) { return Object.fromEntries(new FormData(f)); }\nfunction fmtDate(v) {\n  if (!v) return '';\n  return new Date(v).toLocaleString('en-GB', { timeZone: 'Asia/Kathmandu',\n    day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });\n}\nfunction fmtShort(v) {\n  if (!v) return '';\n  return new Date(v).toLocaleDateString('en-GB', { timeZone: 'Asia/Kathmandu',\n    day: '2-digit', month: 'short', year: 'numeric' });\n}\nfunction roleLabel(r) { return ({ADMIN:'Administrator',RESPONDER:'Responder',RESIDENT:'Resident'})[r] || r; }\nconst HAZARDS = ['Flood','Landslide','Earthquake','Fire','Road accident','Severe storm','Rising water','Land crack','Other emergency','Other concern'];\n\n// ── Shared atoms ──────────────────────────────────────────────────────────────\nfunction StatusBadge({ status }) {\n  return <span className={`status status-${(status||'').toLowerCase()}`} aria-label={`Status: ${status}`}>{status}</span>;\n}\nfunction SeverityBadge({ severity }) {\n  const s = severity || 'Medium';\n  return <span className={`severity severity-${s.toLowerCase()}`}>{s}</span>;\n}\nfunction Spinner() { return <span className=\"spinner\" aria-hidden=\"true\"/>; }\nfunction EmptyState({ icon='📭', title, body }) {\n  return <div className=\"empty-state\">\n    <span className=\"empty-icon\" aria-hidden=\"true\">{icon}</span>\n    <strong>{title}</strong>\n    {body && <p>{body}</p>}\n  </div>;\n}\nfunction Toast({ error, message }) {\n  if (!error && !message) return null;\n  return <>\n    {error && <p className=\"toast toast-error\" role=\"alert\">{error}</p>}\n    {message && <p className=\"toast toast-success\" role=\"status\">{message}</p>}\n  </>;\n}\n\n// ── Auth form ─────────────────────────────────────────────────────────────────\nfunction AuthForm({ onAuthenticated, busy }) {\n  const [register, setRegister] = useState(false);\n  const [name, setName] = useState('');\n  const [email, setEmail] = useState('');\n  const [password, setPassword] = useState('');\n  const [formError, setFormError] = useState('');\n  const [conflict, setConflict] = useState(false);\n  const [submitting, setSubmitting] = useState(false);\n\n  async function handleSubmit(e) {\n    e.preventDefault();\n    if (submitting || busy) return;\n    setFormError('');\n    setConflict(false);\n\n    const trimmedEmail = email.trim().toLowerCase();\n    if (!trimmedEmail) {\n      setFormError('Please enter a valid email address.');\n      return;\n    }\n\n    if (register) {\n      if (!name.trim()) {\n        setFormError('Please enter your full name.');\n        return;\n      }\n      if (password.length < 12) {\n        setFormError('Password must be at least 12 characters long.');\n        return;\n      }\n    } else {\n      if (!password) {\n        setFormError('Please enter your password.');\n        return;\n      }\n    }\n\n    setSubmitting(true);\n    try {\n      const endpoint = register ? '/api/auth/register' : '/api/auth/login';\n      const payload = register\n        ? { name: name.trim(), email: trimmedEmail, password }\n        : { email: trimmedEmail, password };\n      const user = await request(endpoint, 'POST', payload);\n      onAuthenticated(user);\n    } catch (err) {\n      if (err.status === 409) {\n        setConflict(true);\n        setFormError('An account with this email already exists.');\n      } else if (err.status === 401) {\n        setFormError('Email or password is incorrect.');\n      } else {\n        setFormError(err.message || 'Authentication failed. Please try again.');\n      }\n    } finally {\n      setSubmitting(false);\n    }\n  }\n\n  function toggleMode() {\n    setRegister(r => !r);\n    setFormError('');\n    setConflict(false);\n  }\n\n  function switchToSignIn() {\n    setRegister(false);\n    setConflict(false);\n    setFormError('');\n  }\n\n  const isWorking = submitting || busy;\n\n  return (\n    <section className=\"auth-panel panel\">\n      <div className=\"auth-header\">\n        <span className=\"brand-mark-lg\" aria-hidden=\"true\">CDW</span>\n        <p className=\"eyebrow\">COMMUNITY DISASTER WATCH</p>\n        <h2>{register ? 'Create your account' : 'Sign in to your account'}</h2>\n        <p className=\"hint\">\n          {register\n            ? 'New accounts have resident access. Privileged roles are assigned by an administrator.'\n            : 'Sign in to submit incident reports and receive community notifications.'}\n        </p>\n      </div>\n\n      {formError && !conflict && (\n        <div className=\"auth-alert auth-alert-error\" role=\"alert\">\n          {formError}\n        </div>\n      )}\n\n      {conflict && (\n        <div className=\"auth-alert auth-conflict\" role=\"alert\">\n          <p><strong>Account Already Exists</strong></p>\n          <p>An account for <strong>{email}</strong> is already registered.</p>\n          <button type=\"button\" className=\"primary auth-switch-btn\" onClick={switchToSignIn}>\n            Sign In with this email →\n          </button>\n        </div>\n      )}\n\n      <form onSubmit={handleSubmit}>\n        {register && (\n          <label>\n            Full name\n            <input\n              name=\"name\"\n              value={name}\n              onChange={e => setName(e.target.value)}\n              required\n              maxLength={80}\n              autoComplete=\"name\"\n              placeholder=\"e.g. Ramesh Sharma\"\n              disabled={isWorking}\n            />\n          </label>\n        )}\n        <label>\n          Email address\n          <input\n            name=\"email\"\n            type=\"email\"\n            value={email}\n            onChange={e => {\n              setEmail(e.target.value);\n              if (conflict) setConflict(false);\n            }}\n            required\n            maxLength={254}\n            autoComplete=\"username\"\n            placeholder=\"your@email.com\"\n            disabled={isWorking}\n          />\n        </label>\n        <label>\n          Password\n          <input\n            name=\"password\"\n            type=\"password\"\n            value={password}\n            onChange={e => setPassword(e.target.value)}\n            required\n            minLength={register ? 12 : undefined}\n            maxLength={128}\n            autoComplete={register ? 'new-password' : 'current-password'}\n            placeholder={register ? 'At least 12 characters' : 'Your password'}\n            disabled={isWorking}\n          />\n        </label>\n        <button className=\"primary\" disabled={isWorking} type=\"submit\">\n          {isWorking ? <><Spinner/> Please wait...</> : register ? 'Create account' : 'Sign in'}\n        </button>\n      </form>\n      <button className=\"text-button\" type=\"button\" disabled={isWorking} onClick={toggleMode}>\n        {register ? 'Already registered? Sign in' : 'New here? Create a resident account'}\n      </button>\n    </section>\n  );\n}\n\n// ── Report submission form ────────────────────────────────────────────────────\nfunction ReportForm({ areas, run, busy, onSubmitted }) {\n  const [photo, setPhoto] = useState('');\n  const [photoErr, setPhotoErr] = useState('');\n  const [reading, setReading] = useState(false);\n  const [done, setDone] = useState(false);\n  function choosePhoto(e) {\n    setPhoto(''); setPhotoErr('');\n    const file = e.target.files[0];\n    if (!file) return;\n    if (!['image/jpeg','image/png','image/webp'].includes(file.type) || file.size > 3145728) {\n      setPhotoErr('Choose a JPEG, PNG or WebP photo up to 3 MB.'); e.target.value = ''; return;\n    }\n    setReading(true);\n    const r = new FileReader();\n    r.onload = () => { setPhoto(r.result); setReading(false); };\n    r.onerror = () => { setPhotoErr('Photo could not be read.'); setReading(false); };\n    r.readAsDataURL(file);\n  }\n  if (done) return (\n    <div className=\"submit-success panel\">\n      <span className=\"success-icon\" aria-hidden=\"true\">checkmark</span>\n      <h2>Report submitted successfully</h2>\n      <p>Your observation is saved and administrators have been notified.</p>\n      <button className=\"primary\" onClick={() => setDone(false)}>Submit another report</button>\n    </div>\n  );\n  return (\n    <div className=\"layout\">\n      <form className=\"panel\" onSubmit={e => {\n        e.preventDefault();\n        const form = e.currentTarget;\n        const { evidence, ...body } = fields(form);\n        run(async () => {\n          if (!photo) throw new Error('Select a photo before submitting.');\n          await request('/api/reports', 'POST', { ...body, photo });\n          form.reset(); setPhoto(''); setDone(true); await onSubmitted();\n        });\n      }}>\n        <p className=\"eyebrow\">NEW OBSERVATION</p>\n        <h2>Submit an incident report</h2>\n        <div className=\"form-grid-2\">\n          <label>Incident type <span className=\"required\">*</span>\n            <select name=\"hazard\" required>{HAZARDS.map(h => <option key={h}>{h}</option>)}</select>\n          </label>\n          <label>Severity <span className=\"required\">*</span>\n            <select name=\"severity\" defaultValue=\"Medium\">\n              {['Low','Medium','High','Critical'].map(s => <option key={s}>{s}</option>)}\n            </select>\n          </label>\n        </div>\n        <label>Ward / Area <span className=\"required\">*</span>\n          <select name=\"areaId\" required defaultValue=\"\">\n            <option value=\"\" disabled>Select the affected ward or area</option>\n            {areas.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}\n          </select>\n        </label>\n        <label>Description <span className=\"required\">*</span>\n          <textarea name=\"description\" required maxLength={1000} rows={4}\n            placeholder=\"Describe what you observed: what changed, when, and a nearby landmark. Max 1000 characters.\"/>\n        </label>\n        <div className=\"form-grid-3\">\n          <label>Locality<input name=\"locality\" maxLength={120} placeholder=\"Neighborhood or landmark\"/></label>\n          <label>District<input name=\"district\" maxLength={120} placeholder=\"e.g. Kathmandu\"/></label>\n          <label>Municipality<input name=\"municipality\" maxLength={120} placeholder=\"e.g. KMC\"/></label>\n        </div>\n        <div className=\"form-grid-2\">\n          <label>Latitude (optional)<input name=\"latitude\" type=\"number\" min=\"-90\" max=\"90\" step=\"any\" placeholder=\"e.g. 27.7172\"/></label>\n          <label>Longitude (optional)<input name=\"longitude\" type=\"number\" min=\"-180\" max=\"180\" step=\"any\" placeholder=\"e.g. 85.3240\"/></label>\n        </div>\n        <label>Incident date and time (optional)<input name=\"incidentAt\" type=\"datetime-local\"/></label>\n        <label className=\"upload\">Photo evidence <span className=\"required\">*</span>\n          <input name=\"evidence\" type=\"file\" required accept=\"image/jpeg,image/png,image/webp\" onChange={choosePhoto}/>\n          <small>JPEG, PNG or WebP - Maximum 3 MB</small>\n        </label>\n        {photoErr && <p className=\"toast toast-error\" role=\"alert\">{photoErr}</p>}\n        {photo && <img className=\"preview\" src={photo} alt=\"Selected observation preview\"/>}\n        <button className=\"primary\" disabled={busy || reading || !areas.length} type=\"submit\">\n          {busy ? <><Spinner/> Saving...</> : 'Submit observation'}\n        </button>\n        {!areas.length && <p className=\"hint\">No ward areas configured. Contact the administrator.</p>}\n      </form>\n      <aside>\n        <div className=\"panel\">\n          <p className=\"eyebrow\">REPORTING GUIDELINES</p>\n          <h3>Every observation matters</h3>\n          <ol className=\"guide-steps\">\n            <li>Take a photo from a safe location</li>\n            <li>Select the affected ward and describe the change</li>\n            <li>Add location details if known</li>\n            <li>Track your report under My Reports</li>\n          </ol>\n          <hr/>\n          <p className=\"hint\">Do not approach a hazardous area to gather evidence. Your report and photo are visible only to you and authorized reviewers.</p>\n        </div>\n        <div className=\"panel muted\">\n          <p className=\"eyebrow\">AUTOMATED ANALYSIS</p>\n          <h3>Weather-assisted review</h3>\n          <p className=\"hint\">After submission, an automated system adds weather context for reviewer consideration. It does not interpret your photo or predict a disaster.</p>\n        </div>\n      </aside>\n    </div>\n  );\n}\n\n// ── My Reports (resident view) ────────────────────────────────────────────────\nfunction MyReports({ reports, run, busy, refresh }) {\n  return (\n    <section className=\"panel\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">MY SUBMISSIONS</p><h2>Your reported incidents</h2></div>\n        <button disabled={busy} onClick={() => run(refresh)}>Refresh</button>\n      </div>\n      {reports.length === 0\n        ? <EmptyState icon=\"📋\" title=\"No reports yet\" body=\"Use Submit Report to report an incident in your area.\"/>\n        : <div className=\"reports\">{reports.map(r => (\n            <article key={r.id}>\n              <img src={`/api/reports/${r.id}/photo`} alt={`${r.hazard} in ${r.area?.name}`} loading=\"lazy\"/>\n              <div>\n                <div className=\"badge-row\"><StatusBadge status={r.status}/><SeverityBadge severity={r.severity}/></div>\n                <h3>{r.hazard}</h3>\n                <strong>{r.area?.name}</strong>\n                <p className=\"description\">{r.description}</p>\n                <small>Submitted: {fmtDate(r.createdAt)}</small>\n                {r.incidentAt && <><br/><small>Incident: {fmtDate(r.incidentAt)}</small></>}\n                {r.locality && <><br/><small>Location: {r.locality}{r.district ? ', ' + r.district : ''}</small></>}\n                {r.status === 'Rejected' && r.rejectionReason && <p className=\"hint rejection-note\">Rejection reason: {r.rejectionReason}</p>}\n                {r.status === 'Resolved' && r.resolutionSummary && <p className=\"hint\">Resolution: {r.resolutionSummary}</p>}\n                <p className=\"hint\">Analysis: {r.analysis?.status || 'Unavailable'}</p>\n                <Timeline events={r.events}/>\n              </div>\n            </article>\n          ))}</div>}\n    </section>\n  );\n}\n\n// ── Timeline ──────────────────────────────────────────────────────────────────\nfunction Timeline({ events }) {\n  if (!events || events.length === 0) return null;\n  return (\n    <details className=\"activity-details\">\n      <summary>Activity timeline ({events.length} events)</summary>\n      <ol className=\"timeline\">{events.map(ev => (\n        <li key={ev.id}>\n          <span className=\"tl-dot\" aria-hidden=\"true\"/>\n          <div>\n            <strong>{ev.type.replaceAll('_', ' ').toLowerCase()}</strong>\n            {' by '}{ev.actor?.name || 'System'}\n            {ev.note && <span className=\"tl-note\"> - {ev.note}</span>}\n            <br/><small>{fmtDate(ev.createdAt)}</small>\n          </div>\n        </li>\n      ))}</ol>\n    </details>\n  );\n}\n\n// ── Community feed ────────────────────────────────────────────────────────────\nfunction CommunityFeed({ reports, areas, run, busy, refresh }) {\n  const [areaId, setAreaId] = useState('');\n  const [status, setStatus] = useState('');\n  const [severity, setSeverity] = useState('');\n  const [search, setSearch] = useState('');\n  const visible = reports.filter(r =>\n    (!areaId || r.areaId === areaId) && (!status || r.status === status) &&\n    (!severity || r.severity === severity) &&\n    (!search.trim() || (r.hazard+' '+r.description+' '+(r.area?.name||'')+' '+(r.locality||'')).toLowerCase().includes(search.trim().toLowerCase()))\n  );\n  return (\n    <section className=\"panel\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">COMMUNITY OBSERVATIONS</p><h2>Know what has been reported</h2></div>\n        <button disabled={busy} onClick={() => run(refresh)}>Refresh</button>\n      </div>\n      <p className=\"hint\">Observations are unverified. Photo evidence is withheld for privacy.</p>\n      <div className=\"filter-bar\">\n        <label>Search<input type=\"search\" value={search} onChange={e => setSearch(e.target.value)} placeholder=\"Type, description, or area\"/></label>\n        <label>Area<select value={areaId} onChange={e => setAreaId(e.target.value)}>\n          <option value=\"\">All areas</option>{areas.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}\n        </select></label>\n        <label>Status<select value={status} onChange={e => setStatus(e.target.value)}>\n          <option value=\"\">All statuses</option>{['Reported','Verified','Responding','Resolved','Rejected'].map(s => <option key={s}>{s}</option>)}\n        </select></label>\n        <label>Severity<select value={severity} onChange={e => setSeverity(e.target.value)}>\n          <option value=\"\">All severities</option>{['Critical','High','Medium','Low'].map(s => <option key={s}>{s}</option>)}\n        </select></label>\n      </div>\n      {visible.length === 0\n        ? <EmptyState icon=\"🔍\" title={reports.length ? 'No incidents match filters' : 'No observations yet'}\n            body={reports.length ? 'Try adjusting your filters.' : 'Be the first to report a concern.'}/>\n        : <div className=\"reports\">{visible.map(r => (\n            <article key={r.id}>\n              <div className=\"art-img-placeholder\" aria-hidden=\"true\">📷</div>\n              <div>\n                <div className=\"badge-row\"><StatusBadge status={r.status}/><SeverityBadge severity={r.severity}/></div>\n                <h3>{r.hazard}</h3>\n                <strong>{r.area?.name}</strong>\n                <p className=\"description\">{r.description?.slice(0,200)}{r.description?.length > 200 ? '...' : ''}</p>\n                <small>Reported: {fmtDate(r.createdAt)}</small>\n              </div>\n            </article>\n          ))}</div>}\n    </section>\n  );\n}\n\n// ── Weather assessment (admin only) ──────────────────────────────────────────\nfunction Assessment({ analysis, retry, busy }) {\n  if (!analysis) return null;\n  return (\n    <div className=\"assessment\">\n      <p className=\"eyebrow\">AUTOMATED CONTEXT - {analysis.status.toUpperCase()}</p>\n      {analysis.status === 'Pending' && <p>Waiting for analysis. Attempts: {analysis.attempts}.</p>}\n      {analysis.status === 'Processing' && <p>Analysis in progress...</p>}\n      {analysis.error && <p className=\"hint\">Last error: {analysis.error}</p>}\n      {analysis.status === 'Failed' && <button disabled={busy} onClick={retry}>Retry analysis</button>}\n      {analysis.result && <>\n        <p>{analysis.result.summary}</p>\n        <p>{analysis.result.weatherContext}</p>\n        <strong>Uncertainties</strong><ul>{analysis.result.uncertainties.map((x,i)=><li key={i}>{x}</li>)}</ul>\n        <strong>Review questions</strong><ul>{analysis.result.reviewQuestions.map((x,i)=><li key={i}>{x}</li>)}</ul>\n        <p className=\"hint\">{analysis.result.disclaimer}</p>\n        <small>Model: {analysis.model} - {Math.round(analysis.result.durationMs/1000)}s - {fmtDate(analysis.completedAt)} Nepal time</small>\n      </>}\n    </div>\n  );\n}\n\n// ── Admin: incident list ──────────────────────────────────────────────────────\nfunction AdminReports({ reports, areas, teams, run, busy, refresh }) {\n  const [areaId, setAreaId] = useState('');\n  const [status, setStatus] = useState('');\n  const [severity, setSeverity] = useState('');\n  const [search, setSearch] = useState('');\n  const [teamPick, setTeamPick] = useState({});\n  const [pending, setPending] = useState(null);\n  const [note, setNote] = useState('');\n  const visible = reports.filter(r =>\n    (!areaId || r.areaId === areaId) && (!status || r.status === status) &&\n    (!severity || r.severity === severity) &&\n    (!search.trim() || (r.id+' '+r.hazard+' '+r.description+' '+(r.area?.name||'')+' '+(r.locality||'')).toLowerCase().includes(search.trim().toLowerCase()))\n  );\n  return (\n    <section className=\"panel\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">ASSIGNED AREA REPORTS</p><h2>Review and manage incidents</h2></div>\n        <button disabled={busy} onClick={() => run(refresh)}>Refresh</button>\n      </div>\n      <div className=\"filter-bar\">\n        <label>Search<input type=\"search\" value={search} onChange={e=>setSearch(e.target.value)} placeholder=\"ID, type, or description\"/></label>\n        <label>Area<select value={areaId} onChange={e=>setAreaId(e.target.value)}>\n          <option value=\"\">All areas</option>{areas.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}\n        </select></label>\n        <label>Status<select value={status} onChange={e=>setStatus(e.target.value)}>\n          <option value=\"\">All</option>{['Reported','Verified','Responding','Resolved','Rejected'].map(s=><option key={s}>{s}</option>)}\n        </select></label>\n        <label>Severity<select value={severity} onChange={e=>setSeverity(e.target.value)}>\n          <option value=\"\">All</option>{['Critical','High','Medium','Low'].map(s=><option key={s}>{s}</option>)}\n        </select></label>\n      </div>\n      {visible.length === 0\n        ? <EmptyState icon=\"📂\" title={reports.length ? 'No incidents match filters' : 'No incidents in your assigned areas'}/>\n        : <div className=\"reports\">{visible.map(r => (\n            <article key={r.id} className=\"admin-article\">\n              <img src={`/api/reports/${r.id}/photo`} alt={`${r.hazard} in ${r.area?.name}`} loading=\"lazy\"/>\n              <div>\n                <div className=\"badge-row\"><StatusBadge status={r.status}/><SeverityBadge severity={r.severity}/></div>\n                <h3>{r.hazard}</h3>\n                <strong>{r.area?.name}</strong>\n                <small className=\"incident-id\">ID: {r.id}</small>\n                <p className=\"description\">{r.description}</p>\n                {r.locality && <small>Location: {r.locality}{r.district?', '+r.district:''}{r.municipality?', '+r.municipality:''}</small>}\n                {r.latitude != null && <><br/><small>Coordinates: {r.latitude.toFixed(5)}, {r.longitude?.toFixed(5)}</small></>}\n                <br/><small>Submitted: {fmtDate(r.createdAt)}</small>\n                {r.incidentAt && <><br/><small>Incident: {fmtDate(r.incidentAt)}</small></>}\n                {r.rejectionReason && <p className=\"hint\">Rejection: {r.rejectionReason}</p>}\n                {r.resolutionSummary && <p className=\"hint\">Resolution: {r.resolutionSummary}</p>}\n                <div className=\"admin-actions\">\n                  <label>Incident action\n                    <select value={r.status} disabled={busy || ['Resolved','Rejected'].includes(r.status)}\n                      onChange={ev => {\n                        const s = ev.target.value;\n                        if (s === 'Rejected' || s === 'Resolved') { setNote(''); setPending({ r, s }); return; }\n                        run(async () => { await request(`/api/reports/${r.id}`, 'PATCH', { status: s }); await refresh(); },\n                          s === 'Verified' ? 'Verified. This does not confirm physical deployment.' : `Status: ${s}`);\n                      }}>\n                      {r.status === 'Reported' && <><option value=\"Reported\">Reported - Awaiting review</option><option value=\"Verified\">Verify report</option><option value=\"Rejected\">Reject report</option></>}\n                      {r.status === 'Verified' && <><option value=\"Verified\">Verified</option><option value=\"Responding\">Mark Responding</option><option value=\"Resolved\">Resolve incident</option></>}\n                      {r.status === 'Responding' && <><option value=\"Responding\">Responding</option><option value=\"Resolved\">Resolve incident</option></>}\n                      {['Resolved','Rejected'].includes(r.status) && <option value={r.status}>{r.status} - Final</option>}\n                    </select>\n                  </label>\n                  {r.status === 'Verified' && teams.length > 0 && (\n                    <label>Assign response team\n                      <div className=\"assign-row\">\n                        <select value={teamPick[r.id] || ''} onChange={e => setTeamPick(c => ({...c, [r.id]: e.target.value}))}>\n                          <option value=\"\">Select active team...</option>\n                          {teams.map(t => <option key={t.id} value={t.id}>{t.organization?.name} - {t.name}</option>)}\n                        </select>\n                        <button disabled={busy || !teamPick[r.id]} onClick={() => run(async () => {\n                          await request(`/api/reports/${r.id}/assignments`, 'POST', { teamId: teamPick[r.id] });\n                          await refresh();\n                        }, 'Assignment recorded.')}>Assign</button>\n                      </div>\n                    </label>\n                  )}\n                </div>\n                {r.incidentAssignments?.length > 0 && (\n                  <div className=\"assignment-list\">\n                    {r.incidentAssignments.map(a => (\n                      <div key={a.id} className=\"assignment-chip\">\n                        <span>🚒 {a.team?.organization?.name} / {a.team?.name}</span>\n                        <span className={a.acknowledgedAt ? 'ack-yes' : 'ack-pending'}>\n                          {a.acknowledgedAt ? 'Acknowledged ' + fmtShort(a.acknowledgedAt) : 'Awaiting acknowledgement'}\n                        </span>\n                      </div>\n                    ))}\n                  </div>\n                )}\n                <Timeline events={r.events}/>\n                <Assessment analysis={r.analysis} busy={busy} retry={() => run(async () => {\n                  await request(`/api/reports/${r.id}/retry`, 'POST', {}); await refresh();\n                })}/>\n              </div>\n            </article>\n          ))}</div>}\n      {pending && (\n        <div className=\"dialog-backdrop\">\n          <section className=\"confirm-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"confirm-title\">\n            <p className=\"eyebrow\">CONFIRM ACTION</p>\n            <h2 id=\"confirm-title\">{pending.s === 'Rejected' ? 'Reject this report?' : 'Resolve this incident?'}</h2>\n            <p>{pending.s === 'Rejected' ? 'The reporter will see that the report was rejected.' : 'Record a resolution summary.'}</p>\n            <label>{pending.s === 'Rejected' ? 'Rejection reason' : 'Resolution summary'}\n              <textarea autoFocus rows={4} maxLength={pending.s === 'Rejected' ? 500 : 1000}\n                required value={note} onChange={e=>setNote(e.target.value)}\n                placeholder={pending.s === 'Rejected' ? 'e.g. Observation does not match a hazard. No corroborating reports.' : 'e.g. Area inspected and cleared by ward office.'}/>\n            </label>\n            <div className=\"dialog-actions\">\n              <button disabled={busy} onClick={() => setPending(null)}>Cancel</button>\n              <button className={pending.s === 'Rejected' ? 'danger' : 'primary'}\n                disabled={busy || !note.trim()}\n                onClick={() => run(async () => {\n                  const payload = pending.s === 'Rejected' ? { status: 'Rejected', reason: note.trim() } : { status: 'Resolved', resolutionSummary: note.trim() };\n                  await request(`/api/reports/${pending.r.id}`, 'PATCH', payload);\n                  setPending(null); await refresh();\n                }, pending.s + ' recorded.')}>\n                {busy ? <><Spinner/> Saving...</> : `Confirm ${pending.s}`}\n              </button>\n            </div>\n          </section>\n        </div>\n      )}\n    </section>\n  );\n}\n\n// ── Admin: analytics ──────────────────────────────────────────────────────────\nfunction Distribution({ title, values }) {\n  const entries = Object.entries(values || {}).sort((a,b) => b[1]-a[1]);\n  const max = Math.max(1, ...entries.map(([,c]) => c));\n  return (\n    <section className=\"distribution\" aria-label={title + ' breakdown'}>\n      <h3>{title}</h3>\n      {entries.length ? <ul>{entries.map(([label, count]) => (\n        <li key={label}>\n          <div className=\"distribution-label\"><span>{label}</span><strong>{count}</strong></div>\n          <div className=\"distribution-track\" aria-hidden=\"true\"><span style={{ width: Math.max(3, count/max*100) + '%' }}/></div>\n        </li>\n      ))}</ul> : <p className=\"hint\">No data.</p>}\n    </section>\n  );\n}\nfunction AdminAnalytics({ analytics }) {\n  if (!analytics) return <p className=\"hint\">No analytics available.</p>;\n  const metrics = [\n    ['Total', analytics.total, 'metric-neutral'],\n    ['Awaiting review', analytics.byStatus?.Reported || 0, 'metric-blue'],\n    ['Verified', analytics.byStatus?.Verified || 0, 'metric-blue'],\n    ['Responding', analytics.byStatus?.Responding || 0, 'metric-orange'],\n    ['Resolved', analytics.byStatus?.Resolved || 0, 'metric-green'],\n    ['Rejected', analytics.byStatus?.Rejected || 0, 'metric-red'],\n  ];\n  return (\n    <section className=\"dashboard-overview\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">YOUR ASSIGNED JURISDICTION</p><h2>Operational overview</h2></div>\n        <span className=\"data-caption\">Live counts - assigned areas only</span>\n      </div>\n      <div className=\"metric-grid\">\n        {metrics.map(([label, value, cls]) => (\n          <div key={label} className={`metric-card ${cls}`}><span>{label}</span><strong>{value}</strong></div>\n        ))}\n      </div>\n      {analytics.total === 0 ? <p className=\"hint\" style={{marginTop:'16px'}}>No incidents in your assigned areas yet.</p>\n        : <div className=\"distribution-grid\">\n            <Distribution title=\"By severity\" values={analytics.bySeverity}/>\n            <Distribution title=\"By incident type\" values={analytics.byType}/>\n          </div>}\n    </section>\n  );\n}\n\n// ── Admin: User management ────────────────────────────────────────────────────\nfunction AdminUsers({ run, busy, currentUserId }) {\n  const [users, setUsers] = useState(null);\n  const load = useCallback(async () => { setUsers(await request('/api/admin/users')); }, []);\n  useEffect(() => { run(load); }, []);\n  if (!users) return <div className=\"panel\"><div className=\"loading-state\"><Spinner/><span>Loading users...</span></div></div>;\n  return (\n    <section className=\"panel\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">USER MANAGEMENT</p><h2>All registered accounts</h2></div>\n        <button disabled={busy} onClick={() => run(load)}>Refresh</button>\n      </div>\n      <p className=\"hint\">Role changes are immediate. You cannot change your own role. Public registration always creates a RESIDENT.</p>\n      <div className=\"table-scroll\">\n        <table className=\"data-table\">\n          <thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Registered</th><th>Change Role</th></tr></thead>\n          <tbody>{users.map(u => (\n            <tr key={u.id} className={u.id === currentUserId ? 'row-self' : ''}>\n              <td>{u.name}</td>\n              <td>{u.email}</td>\n              <td><span className={`role-badge role-${u.role.toLowerCase()}`}>{roleLabel(u.role)}</span></td>\n              <td><small>{fmtShort(u.createdAt)}</small></td>\n              <td>{u.id !== currentUserId ? (\n                <select className=\"role-select\" value={u.role} disabled={busy}\n                  onChange={e => run(async () => {\n                    await request(`/api/admin/users/${u.id}/role`, 'PATCH', { role: e.target.value });\n                    await load();\n                  }, 'Role updated.')}>\n                  <option value=\"RESIDENT\">Resident</option>\n                  <option value=\"RESPONDER\">Responder</option>\n                  <option value=\"ADMIN\">Administrator</option>\n                </select>\n              ) : <span className=\"hint\">You</span>}</td>\n            </tr>\n          ))}</tbody>\n        </table>\n      </div>\n    </section>\n  );\n}\n\n// ── Admin: Organizations & Teams ──────────────────────────────────────────────\nfunction AdminOrganizations({ run, busy }) {\n  const [orgs, setOrgs] = useState(null);\n  const [responders, setResponders] = useState([]);\n  const [showOrgForm, setShowOrgForm] = useState(false);\n  const [showTeamFor, setShowTeamFor] = useState(null);\n  const [showMemberFor, setShowMemberFor] = useState(null);\n  const load = useCallback(async () => {\n    const [orgData, userData] = await Promise.all([request('/api/admin/organizations'), request('/api/admin/users')]);\n    setOrgs(orgData); setResponders(userData.filter(u => u.role === 'RESPONDER'));\n  }, []);\n  useEffect(() => { run(load); }, []);\n  if (!orgs) return <div className=\"panel\"><div className=\"loading-state\"><Spinner/><span>Loading...</span></div></div>;\n  return (\n    <section className=\"panel\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">RESPONSE ORGANIZATIONS</p><h2>Organizations and teams</h2></div>\n        <button onClick={() => setShowOrgForm(v => !v)}>+ New organization</button>\n      </div>\n      {showOrgForm && (\n        <form className=\"inline-form\" onSubmit={e => {\n          e.preventDefault();\n          const { name, type, jurisdiction } = fields(e.currentTarget);\n          run(async () => { await request('/api/admin/organizations', 'POST', { name, type, jurisdiction });\n            e.target.reset(); setShowOrgForm(false); await load(); }, 'Organization created.');\n        }}>\n          <h3>New response organization</h3>\n          <div className=\"form-grid-3\">\n            <label>Name <span className=\"required\">*</span><input name=\"name\" required maxLength={120} placeholder=\"e.g. Nepal Red Cross\"/></label>\n            <label>Type <span className=\"required\">*</span><input name=\"type\" required maxLength={80} placeholder=\"e.g. Humanitarian NGO\"/></label>\n            <label>Jurisdiction<input name=\"jurisdiction\" maxLength={160} placeholder=\"e.g. Kathmandu District\"/></label>\n          </div>\n          <div className=\"form-actions\">\n            <button type=\"button\" onClick={() => setShowOrgForm(false)}>Cancel</button>\n            <button className=\"primary\" disabled={busy} type=\"submit\">Create organization</button>\n          </div>\n        </form>\n      )}\n      {orgs.length === 0\n        ? <EmptyState icon=\"🏢\" title=\"No organizations yet\" body=\"Create a response organization to manage teams and incident assignments.\"/>\n        : orgs.map(org => (\n          <div key={org.id} className=\"org-card\">\n            <div className=\"org-header\">\n              <div>\n                <strong>{org.name}</strong>\n                <small className=\"org-meta\">{org.type}{org.jurisdiction ? ' - ' + org.jurisdiction : ''}</small>\n              </div>\n              <button onClick={() => setShowTeamFor(showTeamFor === org.id ? null : org.id)}>+ Add team</button>\n            </div>\n            {showTeamFor === org.id && (\n              <form className=\"inline-form\" onSubmit={e => {\n                e.preventDefault();\n                const { name } = fields(e.currentTarget);\n                run(async () => { await request(`/api/admin/organizations/${org.id}/teams`, 'POST', { name });\n                  e.target.reset(); setShowTeamFor(null); await load(); }, 'Team created.');\n              }}>\n                <label>Team name <span className=\"required\">*</span><input name=\"name\" required maxLength={120} placeholder=\"e.g. Alpha Response Unit\"/></label>\n                <div className=\"form-actions\">\n                  <button type=\"button\" onClick={() => setShowTeamFor(null)}>Cancel</button>\n                  <button className=\"primary\" disabled={busy} type=\"submit\">Create team</button>\n                </div>\n              </form>\n            )}\n            {org.teams?.length > 0 ? org.teams.map(team => (\n              <div key={team.id} className=\"team-card\">\n                <div className=\"team-header\">\n                  <span>🚒 {team.name}</span>\n                  <button onClick={() => setShowMemberFor(showMemberFor === team.id ? null : team.id)}>+ Add member</button>\n                </div>\n                {showMemberFor === team.id && (\n                  responders.length > 0 ? (\n                    <form className=\"inline-form\" onSubmit={e => {\n                      e.preventDefault();\n                      const { userId } = fields(e.currentTarget);\n                      run(async () => { await request(`/api/admin/teams/${team.id}/members/${userId}`, 'PUT', {});\n                        e.target.reset(); setShowMemberFor(null); await load(); }, 'Member added.');\n                    }}>\n                      <label>Select responder\n                        <select name=\"userId\" required>\n                          <option value=\"\">Choose responder account...</option>\n                          {responders.map(u => <option key={u.id} value={u.id}>{u.name} ({u.email})</option>)}\n                        </select>\n                      </label>\n                      <div className=\"form-actions\">\n                        <button type=\"button\" onClick={() => setShowMemberFor(null)}>Cancel</button>\n                        <button className=\"primary\" disabled={busy} type=\"submit\">Add to team</button>\n                      </div>\n                    </form>\n                  ) : <p className=\"hint\">No responder accounts exist. Assign RESPONDER role to a user first.</p>\n                )}\n                {team.members?.length > 0\n                  ? <ul className=\"member-list\">{team.members.map(m => <li key={m.userId}>👤 {m.user?.name}</li>)}</ul>\n                  : <p className=\"hint team-empty\">No members assigned yet.</p>}\n              </div>\n            )) : <p className=\"hint\">No teams in this organization.</p>}\n          </div>\n        ))}\n    </section>\n  );\n}\n\n// ── Responder dashboard ───────────────────────────────────────────────────────\nfunction ResponderDashboard({ run, busy }) {\n  const [assignments, setAssignments] = useState(null);\n  const [notes, setNotes] = useState({});\n  const load = useCallback(async () => { setAssignments(await request('/api/responder/assignments')); }, []);\n  useEffect(() => { run(load); }, []);\n  if (!assignments) return <div className=\"panel\"><div className=\"loading-state\"><Spinner/><span>Loading assignments...</span></div></div>;\n  return (\n    <section className=\"panel\">\n      <div className=\"section-title\">\n        <div><p className=\"eyebrow\">RESPONDER WORKSPACE</p><h2>Your assigned incidents</h2></div>\n        <button disabled={busy} onClick={() => run(load)}>Refresh</button>\n      </div>\n      <p className=\"hint\">Acknowledge your assignment to record awareness. Record response progress when work begins. Acknowledgement does not confirm physical deployment.</p>\n      {assignments.length === 0\n        ? <EmptyState icon=\"✅\" title=\"No active assignments\" body=\"Contact your administrator if you expect an assignment.\"/>\n        : <div className=\"reports\">{assignments.map(a => (\n            <article key={a.id} className=\"responder-article\">\n              <div>\n                <div className=\"badge-row\">\n                  <StatusBadge status={a.report?.status}/>\n                  <SeverityBadge severity={a.report?.severity}/>\n                  <span className={'ack-badge ' + (a.acknowledgedAt ? 'ack-yes' : 'ack-pending')}>\n                    {a.acknowledgedAt ? 'Acknowledged' : 'Awaiting acknowledgement'}\n                  </span>\n                </div>\n                <h3>{a.report?.hazard}</h3>\n                <strong>{a.report?.area?.name}</strong>\n                <p className=\"hint\">Team: {a.team?.organization?.name} / {a.team?.name}</p>\n                <p className=\"description\">{a.report?.description}</p>\n                {a.report?.locality && <small>Location: {a.report.locality}{a.report.district ? ', ' + a.report.district : ''}</small>}\n                <br/><small>Assigned: {fmtDate(a.assignedAt)}</small>\n                {a.acknowledgedAt && <><br/><small>Acknowledged: {fmtDate(a.acknowledgedAt)}</small></>}\n                <div className=\"responder-actions\">\n                  {!a.acknowledgedAt && (\n                    <button className=\"primary\" disabled={busy} onClick={() => run(async () => {\n                      await request(`/api/assignments/${a.id}/acknowledge`, 'POST', {});\n                      await load();\n                    }, 'Assignment acknowledged.')}>Acknowledge assignment</button>\n                  )}\n                  {a.acknowledgedAt && a.report?.status === 'Verified' && (\n                    <div className=\"progress-form\">\n                      <label>Response progress note\n                        <textarea rows={2} maxLength={500} value={notes[a.id] || ''} onChange={e => setNotes(n => ({...n, [a.id]: e.target.value}))}\n                          placeholder=\"e.g. Team on site. Assessing extent.\"/>\n                      </label>\n                      <button className=\"primary\" disabled={busy} onClick={() => run(async () => {\n                        await request(`/api/assignments/${a.id}/responding`, 'POST', { note: notes[a.id] || '' });\n                        await load();\n                      }, 'Response progress recorded.')}>Record response progress</button>\n                    </div>\n                  )}\n                  {a.report?.status === 'Responding' && <p className=\"hint\">Incident is in Responding state. Contact your administrator to resolve.</p>}\n                </div>\n                <Timeline events={a.report?.events}/>\n              </div>\n            </article>\n          ))}</div>}\n    </section>\n  );\n}\n\n// ── Incident map ──────────────────────────────────────────────────────────────\nfunction IncidentMap({ reports }) {\n  const mapped = reports.filter(r => r.latitude != null && r.longitude != null);\n  return (\n    <section className=\"panel\">\n      <p className=\"eyebrow\">INCIDENT MAP</p>\n      <h2>Geographic overview</h2>\n      <p className=\"hint\">{mapped.length} of {reports.length} incidents have recorded coordinates.</p>\n      <div className=\"map-placeholder\" role=\"img\" aria-label=\"Incident map - coordinate list below\">\n        <div className=\"map-overlay\">\n          <span style={{fontSize:'2.5rem'}}>🗺️</span>\n          <p>Interactive map requires a configured map provider (e.g. Leaflet + OpenStreetMap).</p>\n          <p className=\"hint\">Incidents with coordinates are listed below.</p>\n        </div>\n      </div>\n      {mapped.length > 0 ? (\n        <div className=\"table-scroll\" style={{marginTop:'16px'}}>\n          <table className=\"data-table\">\n            <thead><tr><th>Incident</th><th>Area</th><th>Status</th><th>Severity</th><th>Latitude</th><th>Longitude</th><th>Submitted</th></tr></thead>\n            <tbody>{mapped.map(r => (\n              <tr key={r.id}>\n                <td>{r.hazard}</td><td>{r.area?.name}</td>\n                <td><StatusBadge status={r.status}/></td><td><SeverityBadge severity={r.severity}/></td>\n                <td>{r.latitude?.toFixed(5)}</td><td>{r.longitude?.toFixed(5)}</td>\n                <td><small>{fmtShort(r.createdAt)}</small></td>\n              </tr>\n            ))}</tbody>\n          </table>\n        </div>\n      ) : <EmptyState icon=\"📍\" title=\"No incidents with coordinates\" body=\"Reports with coordinates will appear here.\"/>}\n    </section>\n  );\n}\n\n// ── Notifications view ────────────────────────────────────────────────────────\nfunction NotificationsView({ areas, subscriptions, notifications, run, busy, refresh }) {\n  const [selected, setSelected] = useState(subscriptions);\n  useEffect(() => setSelected(subscriptions), [subscriptions.join('|')]);\n  const unread = notifications.filter(n => !n.readAt).length;\n  return (\n    <div className=\"layout\">\n      <section className=\"panel\">\n        <div className=\"section-title\">\n          <div><p className=\"eyebrow\">NOTIFICATIONS</p>\n            <h2>Your updates {unread > 0 && <span className=\"notif-count\">{unread}</span>}</h2>\n          </div>\n          <button disabled={busy} onClick={() => run(refresh)}>Refresh</button>\n        </div>\n        <p className=\"hint\">In-app notifications only. No SMS or push notifications are sent.</p>\n        {notifications.length === 0\n          ? <EmptyState icon=\"🔔\" title=\"No notifications yet\" body=\"Subscribe to an area to receive new report notifications.\"/>\n          : notifications.map(n => (\n              <div className={'notification ' + (n.readAt ? '' : 'unread')} key={n.id}>\n                <p>{n.message}</p>\n                <small>{fmtDate(n.createdAt)} - Nepal time</small>\n                {!n.readAt && <button disabled={busy} onClick={() => run(async () => {\n                  await request(`/api/notifications/${n.id}`, 'PATCH', {}); await refresh();\n                })}>Mark as read</button>}\n              </div>\n            ))}\n      </section>\n      <aside className=\"panel\">\n        <p className=\"eyebrow\">AREA SUBSCRIPTIONS</p>\n        <h2>Follow your community</h2>\n        <p className=\"hint\">Subscriptions apply to future reports and updates.</p>\n        {areas.map(area => (\n          <label className=\"checkbox\" key={area.id}>\n            <input type=\"checkbox\" checked={selected.includes(area.id)} onChange={e => {\n              setSelected(e.target.checked ? [...selected, area.id] : selected.filter(id => id !== area.id));\n            }}/>{area.name}\n          </label>\n        ))}\n        <button className=\"primary\" disabled={busy} style={{marginTop:'12px'}} onClick={() => run(async () => {\n          await request('/api/subscriptions', 'PUT', { areaIds: selected }); await refresh();\n        }, 'Subscriptions saved.')}>Save subscriptions</button>\n      </aside>\n    </div>\n  );\n}\n\n// ── Root App ──────────────────────────────────────────────────────────────────\nfunction App() {\n  const [user, setUser] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [view, setView] = useState('report');\n  const [areas, setAreas] = useState([]);\n  const [reports, setReports] = useState([]);\n  const [adminReports, setAdminReports] = useState([]);\n  const [adminTeams, setAdminTeams] = useState([]);\n  const [analytics, setAnalytics] = useState(null);\n  const [subscriptions, setSubscriptions] = useState([]);\n  const [notifications, setNotifications] = useState([]);\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState('');\n  const [message, setMessage] = useState('');\n  const [menuOpen, setMenuOpen] = useState(false);\n\n  async function refresh(u = user) {\n    if (!u) return;\n    const isAdmin = u.role === 'ADMIN';\n    const [areaData, reportData, subData, notifData, adminData, teamData, analyticsData] = await Promise.all([\n      request('/api/areas'), request('/api/reports'), request('/api/subscriptions'), request('/api/notifications'),\n      isAdmin ? request('/api/admin/reports') : Promise.resolve([]),\n      isAdmin ? request('/api/admin/teams') : Promise.resolve([]),\n      isAdmin ? request('/api/admin/analytics') : Promise.resolve(null),\n    ]);\n    setAreas(areaData); setReports(reportData); setSubscriptions(subData); setNotifications(notifData);\n    setAdminReports(adminData); setAdminTeams(teamData); setAnalytics(analyticsData);\n  }\n\n  async function run(action, success = '') {\n    setBusy(true); setError(''); setMessage('');\n    try { await action(); if (success) setMessage(success); }\n    catch (e) { setError(e.message); if (e.status === 401) { setUser(null); setView('report'); } }\n    finally { setBusy(false); }\n  }\n\n  useEffect(() => {\n    let mounted = true;\n    request('/api/auth/me')\n      .then(async u => {\n        if (!mounted) return;\n        setUser(u);\n        await refresh(u);\n      })\n      .catch(e => {\n        if (!mounted) return;\n        setUser(null);\n        // HTTP 401 is normal for visitors who have not signed in yet.\n        if (e.status !== 401) {\n          setError('Could not connect to the server. Please verify your connection.');\n        }\n      })\n      .finally(() => {\n        if (mounted) setLoading(false);\n      });\n    return () => { mounted = false; };\n  }, []);\n\n  useEffect(() => {\n    if (!user) return;\n    const t = setInterval(() => refresh(user).catch(e => { if (e.status === 401) { setUser(null); setView('report'); } }), 20000);\n    return () => clearInterval(t);\n  }, [user]);\n\n  useEffect(() => {\n    if (!menuOpen) return;\n    const h = e => { if (e.key === 'Escape') setMenuOpen(false); };\n    window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);\n  }, [menuOpen]);\n\n  const unread = notifications.filter(n => !n.readAt).length;\n\n  const navItems = !user ? [] : user.role === 'ADMIN' ? [\n    { key: 'admin-overview', label: 'Overview' },\n    { key: 'admin-reports', label: 'Incidents' },\n    { key: 'admin-map', label: 'Map' },\n    { key: 'admin-orgs', label: 'Organizations' },\n    { key: 'admin-users', label: 'Users' },\n    { key: 'notifications', label: `Notifications${unread > 0 ? ' (' + unread + ')' : ''}` },\n  ] : user.role === 'RESPONDER' ? [\n    { key: 'responder', label: 'My Assignments' },\n    { key: 'community', label: 'Community Feed' },\n    { key: 'notifications', label: `Notifications${unread > 0 ? ' (' + unread + ')' : ''}` },\n  ] : [\n    { key: 'report', label: 'Submit Report' },\n    { key: 'my-reports', label: 'My Reports' },\n    { key: 'community', label: 'Community Feed' },\n    { key: 'notifications', label: `Notifications${unread > 0 ? ' (' + unread + ')' : ''}` },\n  ];\n\n  function nav(key) { setView(key); setMenuOpen(false); setError(''); setMessage(''); }\n\n  return (\n    <>\n      <a className=\"skip-link\" href=\"#main-content\">Skip to main content</a>\n      <header>\n        <a className=\"brand\" href=\"/\" aria-label=\"Community Disaster Watch home\">\n          <span className=\"brand-mark\" aria-hidden=\"true\">CDW</span>\n          <span><span>Community</span><strong>Disaster Watch</strong></span>\n        </a>\n        {user ? (\n          <div className=\"account\">\n            <span><strong>{user.name}</strong><small>{roleLabel(user.role)}</small></span>\n            <button disabled={busy} onClick={() => run(async () => {\n              await request('/api/auth/logout', 'POST', {});\n              setUser(null); setView('report'); setNotifications([]);\n            })}>Sign out</button>\n          </div>\n        ) : <span className=\"brand-meta\">COMMUNITY AWARENESS - NEPAL</span>}\n      </header>\n      <main id=\"main-content\">\n        {!user && !loading && (\n          <section className=\"intro\">\n            <div>\n              <p className=\"eyebrow\">OBSERVE. REPORT. STAY INFORMED.</p>\n              <h1>A safer community<br/>starts with awareness.</h1>\n              <p>Share a concerning change in your area. Help local reviewers gather information and keep your community informed.</p>\n            </div>\n            <div className=\"intro-action\">\n              <span className=\"live-dot\" aria-hidden=\"true\"/>\n              <span>Community reporting platform<br/><strong>Himalayan WhiteHouse College - Nepal</strong></span>\n            </div>\n          </section>\n        )}\n        <div className=\"notice\" role=\"note\">\n          <strong>Notice:</strong> Community observations are unverified. This platform supports administrative review and does not issue official emergency warnings.\n        </div>\n        <Toast error={error} message={message}/>\n        {loading ? (\n          <div className=\"loading-state\" role=\"status\"><Spinner/><span>Loading your account...</span></div>\n        ) : !user ? (\n          <AuthForm run={run} busy={busy} onAuthenticated={async u => {\n            setUser(u); setView(u.role === 'ADMIN' ? 'admin-overview' : u.role === 'RESPONDER' ? 'responder' : 'report');\n            await refresh(u);\n          }}/>\n        ) : (\n          <>\n            <div className=\"mobile-nav-bar\">\n              <span>Navigation</span>\n              <button className=\"menu-toggle\" aria-expanded={menuOpen} aria-controls=\"workspace-nav\"\n                onClick={() => setMenuOpen(v => !v)}>{menuOpen ? 'X Close' : 'Menu'}</button>\n            </div>\n            <nav id=\"workspace-nav\" className={menuOpen ? 'nav-open' : ''} aria-label=\"Application views\">\n              {navItems.map(item => (\n                <button key={item.key} disabled={busy} aria-current={view === item.key ? 'page' : undefined}\n                  className={view === item.key ? 'active' : ''} onClick={() => nav(item.key)}>\n                  {item.label}\n                </button>\n              ))}\n            </nav>\n            {view === 'report' && user.role === 'RESIDENT' && <ReportForm areas={areas} run={run} busy={busy} onSubmitted={() => refresh()}/>}\n            {view === 'my-reports' && user.role === 'RESIDENT' && <MyReports reports={reports} run={run} busy={busy} refresh={() => refresh()}/>}\n            {view === 'community' && <CommunityFeed reports={reports} areas={areas} run={run} busy={busy} refresh={() => refresh()}/>}\n            {view === 'admin-overview' && user.role === 'ADMIN' && <AdminAnalytics analytics={analytics}/>}\n            {view === 'admin-reports' && user.role === 'ADMIN' && <AdminReports reports={adminReports} areas={areas} teams={adminTeams} run={run} busy={busy} refresh={() => refresh()}/>}\n            {view === 'admin-map' && user.role === 'ADMIN' && <IncidentMap reports={adminReports}/>}\n            {view === 'admin-orgs' && user.role === 'ADMIN' && <AdminOrganizations run={run} busy={busy}/>}\n            {view === 'admin-users' && user.role === 'ADMIN' && <AdminUsers run={run} busy={busy} currentUserId={user.id}/>}\n            {view === 'responder' && user.role === 'RESPONDER' && <ResponderDashboard run={run} busy={busy}/>}\n            {view === 'notifications' && <NotificationsView areas={areas} subscriptions={subscriptions} notifications={notifications} run={run} busy={busy} refresh={() => refresh()}/>}\n          </>\n        )}\n        <footer>\n          <p>Community Disaster Watch</p>\n          <p>Himalayan WhiteHouse International College - Putalisadak, Kathmandu</p>\n          <p>Affiliated with Purbanchal University</p>\n        </footer>\n      </main>\n    </>\n  );\n}\ncreateRoot(document.getElementById('root')).render(<App/>);\n";

writeFileSync(out, jsx, 'utf8');
console.log('Wrote main.jsx successfully.');
